  final ambient =
      ambientFaBin ?? (useAmbientFaBin ? Platform.environment['FA_BIN'] : null);
  final bin = (faBin != null && faBin.isNotEmpty)
      ? faBin
      : (ambient != null && ambient.isNotEmpty ? ambient : null);
